8	
9	// 本文件保护“接受安装失败后才进入回滚”这一前提在打开本地存储时同样生效：
10	// 开启安装失败回滚的活动中，只要某台设备处于等待回滚、正在回滚、回滚成功、
11	// 回滚失败或回滚超时，就必须能从该设备在同一活动中已经接受的安装结果确认
12	// 安装失败。安装尚未领取、已领取但没有结果，或安装结果为成功，都不能支持
13	// 这些回滚状态；下载失败、其他设备或其他活动的失败记录也不能代替本次安装
14	// 失败。发现矛盾时 Open 返回 ErrCorruptStorage，整个存储不得进入可用状态，
15	// 原文件内容保持不变。
16	
17	// installFailAt 是测试时间线中安装失败被接受的时刻：
18	// 领取下载 +2m、下载成功 +3m、领取安装 +4m、安装失败 +5m。
19	func installFailAt(base time.Time) time.Time { return base.Add(5 * time.Minute) }
20	
21	// buildRollingBase 构造一台处于“正在回滚”的设备：完成下载、安装失败被接受、
22	// 再领取回滚但不完成。withReport 时在等待回滚期间插入一条 seq=2 的普通上报
23	// （版本 v9、空配置），用于让伪造的安装成功结果拥有更小序号、不与当前影子
24	// 对内容；普通上报不改变已接受的安装失败与回滚待办。
25	func buildRollingBase(t *testing.T, withReport bool) (*Store, CampaignSpec) {
26		t.Helper()
27		s := setupUpgrade(t, "d1")
28		spec := rbSpec()
29		createCampaign(t, s, spec)
30		bringOnline(t, s, "d1")
31		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
32		if withReport {
33			if err := s.Report("d1", 2, upBase.Add(6*time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
34				t.Fatalf("plain report: %v", err)
35			}
36		}
37		rb, err := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
38		if err != nil || rb == nil || rb.Kind != StageRollback {
39			t.Fatalf("claim rollback: %v %+v", err, rb)
40		}
41		return s, spec
42	}
43	
44	// finishRollbackSuccess 让正在回滚的设备回滚成功。seq 随是否已有 seq=2 的
45	// 普通上报取 3 或 2；附带上报配置引入 /ok 差异，影子由运行时正常维护。
46	func finishRollbackSuccess(t *testing.T, s *Store, spec CampaignSpec, seq uint64) {
47		t.Helper()
48		rb := findDevice(mustGetCampaign(s, spec.ID), "d1").RollbackID
49		if err := s.SubmitResult(OperationResult{
50			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb,
51			At: upBase.Add(90 * time.Minute), Success: true,
52			Seq: seq, Version: "v1", Config: json.RawMessage(`{"ok":true}`),
53		}); err != nil {
54			t.Fatalf("rollback success: %v", err)
55		}
56	}
57	
58	// finishRollbackFailure 让正在回滚的设备回滚失败。
59	func finishRollbackFailure(t *testing.T, s *Store, spec CampaignSpec) {
60		t.Helper()
61		rb := findDevice(mustGetCampaign(s, spec.ID), "d1").RollbackID
62		if err := s.SubmitResult(OperationResult{
63			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb,
64			At: upBase.Add(9 * time.Minute), Success: false, Reason: "rb boom",
65		}); err != nil {
66			t.Fatalf("rollback failure: %v", err)
67		}
68	}
69	
70	// timeoutRollingBase 把正在回滚的活动推进到截止，设备以回滚阶段超时结束。
71	func timeoutRollingBase(t *testing.T, s *Store, spec CampaignSpec) {
72		t.Helper()
73		if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
74			t.Fatalf("advance to deadline: %v", err)
75		}
76	}
77	
78	// installOpDoc / replaceInstallHistory 定位磁盘上的安装操作与安装结果历史。
79	func installOpDoc(doc map[string]any, campaignID, deviceID string) map[string]any {
80		return campaignDeviceDoc(doc, campaignID, deviceID)["install"].(map[string]any)
81	}
82	
83	// removeInstallHistory 删除该设备保存的安装结果历史条目，返回被删条目是否存在。
84	func removeInstallHistory(doc map[string]any, campaignID, deviceID string) bool {
85		camp := campaignDoc(doc, campaignID)
86		raw, _ := camp["results"].([]any)
87		kept := make([]any, 0, len(raw))
88		found := false
89		for _, r := range raw {
90			rec := r.(map[string]any)
91			if rec["deviceId"] == deviceID && rec["stage"] == StageInstall {
92				found = true
93				continue
94			}
95			kept = append(kept, rec)
96		}
97		camp["results"] = kept
98		return found
99	}
100	
101	// setInstallNoResult 把安装操作改写为“已领取但没有结果”（claimed=true 时）
102	// 或“尚未领取”（claimed=false 时），并清掉全部结果字段；安装失败历史同步删除。
103	// 改写后除“缺少本设备本次安装失败”外的其余记录保持自洽。
104	func setInstallNoResult(doc map[string]any, campaignID, deviceID string, claimed bool) {
105		inst := installOpDoc(doc, campaignID, deviceID)
106		inst["claimed"] = claimed
107		if claimed {
108			if _, ok := inst["claimedAt"]; !ok {
109				inst["claimedAt"] = "2026-10-02T12:04:00Z"
110			}
111		} else {
112			delete(inst, "claimedAt")
113		}
114		inst["hasResult"] = false
115		for _, k := range []string{"success", "reason", "at", "resultSeq", "resultVersion", "resultConfig"} {
116			delete(inst, k)
117		}
118		if !removeInstallHistory(doc, campaignID, deviceID) {
119			panic("test setup: install history missing")
120		}
121	}
122	
123	// setInstallSuccess 把安装操作改写为一条内容自洽的“安装成功”已接受结果
124	// （seq=1，版本等于活动目标 v2，空对象配置），历史条目同步改为安装成功。
125	// 当设备最近已接受更大序号（seq=2 的普通上报或回滚上报）时，这条 seq=1 的
126	// 成功记录属于被后续上报覆盖的历史，恢复核对不要求它与当前影子一致，因此
127	// 除“安装成功不能支持回滚状态”外记录完全合法。
128	func setInstallSuccess(doc map[string]any, campaignID, deviceID string) {
129		inst := installOpDoc(doc, campaignID, deviceID)
130		inst["claimed"] = true
131		if _, ok := inst["claimedAt"]; !ok {
132			inst["claimedAt"] = "2026-10-02T12:04:00Z"
133		}
134		inst["hasResult"] = true
135		inst["success"] = true
136		delete(inst, "reason")
137		if _, ok := inst["at"]; !ok {
138			inst["at"] = "2026-10-02T12:05:00Z"
139		}
140		inst["resultSeq"] = 1
141		inst["resultVersion"] = "v2"
142		inst["resultConfig"] = map[string]any{}
143		camp := campaignDoc(doc, campaignID)
144		raw, _ := camp["results"].([]any)
145		replaced := false
146		for _, r := range raw {
147			rec := r.(map[string]any)
148			if rec["deviceId"] == deviceID && rec["stage"] == StageInstall {
149				rec["success"] = true
150				delete(rec, "reason")
151				rec["version"] = "v2"
152				replaced = true
153			}
154		}
155		if !replaced {
156			panic("test setup: install history missing")
157		}
158	}
159	
160	// setDownloadFailure 把成功下载改写为下载失败（带原因），安装改为尚未领取、
161	// 安装失败历史删除，用来证明下载失败不能代替本次安装失败。回滚目标仍保留。
162	func setDownloadFailure(doc map[string]any, campaignID, deviceID string) {
163		dev := campaignDeviceDoc(doc, campaignID, deviceID)
164		dl := dev["download"].(map[string]any)
165		dl["hasResult"] = true
166		dl["success"] = false
167		dl["reason"] = "dl down"
168		if _, ok := dl["at"]; !ok {
169			dl["at"] = dl["claimedAt"]
170		}
171		inst := dev["install"].(map[string]any)
172		inst["claimed"] = false
173		delete(inst, "claimedAt")
174		inst["hasResult"] = false
175		for _, k := range []string{"success", "reason", "at", "resultSeq", "resultVersion", "resultConfig"} {
176			delete(inst, k)
177		}
178		removeInstallHistory(doc, campaignID, deviceID)
179		camp := campaignDoc(doc, campaignID)
180		raw, _ := camp["results"].([]any)
181		for _, r := range raw {
182			rec := r.(map[string]any)
183			if rec["deviceId"] == deviceID && rec["stage"] == StageDownload {
184				rec["success"] = false
185				rec["reason"] = "dl down"
186				delete(rec, "version")
187			}
188		}
189	}
190	
191	// mutateCase 描述一种“抹掉本设备本次安装失败前提”的磁盘改写。
192	type mutateCase struct {
193		name   string
194		mutate func(doc map[string]any, campaignID, deviceID string)
195	}
196	
197	func rollbackPremiseCases() []mutateCase {
198		return []mutateCase{
199			{
200				name:   "install never claimed",
201				mutate: func(doc map[string]any, id, dev string) { setInstallNoResult(doc, id, dev, false) },
202			},
203			{
204				name:   "install claimed without result",
205				mutate: func(doc map[string]any, id, dev string) { setInstallNoResult(doc, id, dev, true) },
206			},
207			{
208				name:   "install result is success",
209				mutate: func(doc map[string]any, id, dev string) { setInstallSuccess(doc, id, dev) },
210			},
211			{
212				name:   "download failure instead of install failure",
213				mutate: func(doc map[string]any, id, dev string) { setDownloadFailure(doc, id, dev) },
214			},
215		}
216	}
217	
218	// TestRestoreRollbackRequiresInstallFailure 保护核心修复：正在回滚与回滚终态
219	// 此前缺少“已接受本次安装失败”的核对，安装尚未领取、已领取但没有结果、安装
220	// 成功，或只有下载失败的设备也能被恢复成回滚状态、查到回滚待办。这些自洽
221	// （回滚目标非空、操作标识合法、回滚结果与历史一致）的矛盾记录现在都必须在
222	// Open 时整体拒绝。
223	func TestRestoreRollbackRequiresInstallFailure(t *testing.T) {
224		// statusBases 给出每种“修复前未核对”的回滚状态及其磁盘构造方式。
225		// 伪造安装成功/下载失败等情形依赖设备最近已接受 seq=2 的上报，
226		// 因此基座统一带一条等待回滚期间的普通上报（不否定安装失败）。
227		type base struct {
228			status string
229			build  func(t *testing.T) (*Store, CampaignSpec)
230		}
231		bases := []base{
232			{DeviceRollingBack, func(t *testing.T) (*Store, CampaignSpec) {
233				return buildRollingBase(t, true)
234			}},
235			{DeviceRollbackSucceeded, func(t *testing.T) (*Store, CampaignSpec) {
236				s, spec := buildRollingBase(t, true)
237				finishRollbackSuccess(t, s, spec, 3)
238				return s, spec
239			}},
240			{DeviceRollbackFailed, func(t *testing.T) (*Store, CampaignSpec) {
241				s, spec := buildRollingBase(t, true)
242				finishRollbackFailure(t, s, spec)
243				return s, spec
244			}},
245			{DeviceRollbackTimeout, func(t *testing.T) (*Store, CampaignSpec) {
246				s, spec := buildRollingBase(t, true)
247				timeoutRollingBase(t, s, spec)
248				return s, spec
249			}},
250		}
251		for _, b := range bases {
252			for _, mc := range rollbackPremiseCases() {
253				name := b.status + "/" + mc.name
254				t.Run(name, func(t *testing.T) {
255					s, spec := b.build(t)
256					if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != b.status {
257						t.Fatalf("precondition status: got %s want %s", d.Status, b.status)
258					}
259					dir := closeStore(t, s)
260					original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
261						mc.mutate(doc, spec.ID, "d1")
262					})
263					assertReopenCorrupt(t, dir, original)
264				})
265			}
266		}
267	}
268	
269	// TestRestoreAwaitingRollbackTimeoutRequiresInstallFailure 覆盖等待回滚超时
270	// （回滚未领取、无回滚结果）这一形态：它同样必须有已接受的安装失败，
271	// 不能因为没有回滚领取和结果就把缺少安装失败当成正常记录。
272	func TestRestoreAwaitingRollbackTimeoutRequiresInstallFailure(t *testing.T) {
273		for _, mc := range rollbackPremiseCases() {
274			t.Run(mc.name, func(t *testing.T) {
275				s := setupUpgrade(t, "d1")
276				spec := rbSpec()
277				createCampaign(t, s, spec)
278				bringOnline(t, s, "d1")
279				awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
280				if err := s.Report("d1", 2, upBase.Add(6*time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
281					t.Fatalf("plain report: %v", err)
282				}
283				// 不领取回滚，直接推进到截止：等待回滚超时（回滚未领取、无结果）。
284				if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
285					t.Fatal(err)
286				}
287				if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != DeviceRollbackTimeout {
288					t.Fatalf("precondition: %+v", d)
289				}
290				dir := closeStore(t, s)
291				original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
292					mc.mutate(doc, spec.ID, "d1")
293				})
294				assertReopenCorrupt(t, dir, original)
295			})
296		}
297	}
298	
299	// TestRestoreRollbackPremiseOtherFailuresDontCount 证明安装失败前提必须是
300	// “本设备、本活动、本次安装”的失败：同活动另一台设备的安装失败，以及另一个
301	// 正常活动里的回滚记录，都不能代替本设备本次安装失败；即使其余设备与活动
302	// 全部正常，整个存储仍必须拒绝打开，原文件保持不变。
303	func TestRestoreRollbackPremiseOtherFailuresDontCount(t *testing.T) {
304		s := setupUpgrade(t, "d1", "d2", "d3")
305		spec := upSpec()
306		spec.Devices = []string{"d1", "d2"}
307		spec.BatchSize = 2
308		spec.RollbackOnFailure = true
309		createCampaign(t, s, spec)
310		bringOnline(t, s, "d1")
311		bringOnline(t, s, "d2")
312		// 两台设备都安装失败、进入回滚：d2 保留合法的安装失败记录。
313		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
314		awaitRollback(t, s, spec, "d2", upBase.Add(12*time.Minute))
315		if _, err := s.Claim(spec.ID, "d1", upBase.Add(20*time.Minute)); err != nil {
316			t.Fatalf("claim d1 rollback: %v", err)
317		}
318	
319		// 另一个完全正常的回滚活动（d3），重开本应照常可用。
320		other := rbSpec()
321		other.ID = "cmp-other"
322		other.Devices = []string{"d3"}
323		createCampaign(t, s, other)
324		bringOnline(t, s, "d3")
325		inID, _ := awaitRollback(t, s, other, "d3", upBase.Add(22*time.Minute))
326		if inID == "" {
327			t.Fatal("other campaign setup")
328		}
329	
330		dir := closeStore(t, s)
331		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
332			// d1 的安装失败被抹成“已领取但没有结果”，d2 与 cmp-other 不动。
333			setInstallNoResult(doc, spec.ID, "d1", true)
334		})
335		// d2、d3 的合法回滚记录不能让存储部分可用：整个存储必须原样拒绝。
336		assertReopenCorrupt(t, dir, original)
337	}
338	
339	// TestRestoreLegitRollbackStatesKeepProgress 保护合法回滚记录的恢复行为不变：
340	// 安装失败后等待回滚、正在回滚、回滚成功、回滚失败、等待回滚超时与正在回滚
341	// 超时都按原进度、锁定目标与安装失败原因/时间恢复；这些记录即使缺回滚领取
342	// 或回滚结果（超时形态）也照常打开。
343	func TestRestoreLegitRollbackStatesKeepProgress(t *testing.T) {
344		failAt := installFailAt(upBase)
345	
346		t.Run("awaiting rollback", func(t *testing.T) {
347			s := setupUpgrade(t, "d1")
348			spec := rbSpec()
349			createCampaign(t, s, spec)
350			bringOnline(t, s, "d1")
351			awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
352			dir := closeStore(t, s)
353			s2, err := Open(dir)
354			if err != nil {
355				t.Fatalf("reopen: %v", err)
356			}
357			defer s2.Close()
358			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
359			if d.Status != DeviceAwaitingRollback || d.RollbackTarget != "v1" ||
360				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
361				t.Fatalf("awaiting rollback restored: %+v", d)
362			}
363			w, _ := s2.GetDeviceWork("d1")
364			if w.Pending == nil || w.Pending.Kind != StageRollback ||
365				w.PendingClaimed || w.Pending.TargetVersion != "v1" {
366				t.Fatalf("rollback todo restored: %+v", w)
367			}
368		})
369	
370		t.Run("rolling back", func(t *testing.T) {
371			s, spec := buildRollingBase(t, false)
372			rbBefore := findDevice(mustGetCampaign(s, spec.ID), "d1").RollbackID
373			dir := closeStore(t, s)
374			s2, err := Open(dir)
375			if err != nil {
376				t.Fatalf("reopen: %v", err)
377			}
378			defer s2.Close()
379			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
380			if d.Status != DeviceRollingBack || d.RollbackTarget != "v1" ||
381				d.RollbackID != rbBefore ||
382				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
383				t.Fatalf("rolling back restored: %+v", d)
384			}
385			again, err := s2.Claim(spec.ID, "d1", upBase.Add(85*time.Minute))
386			if err != nil || again == nil || again.ID != rbBefore {
387				t.Fatalf("claimed rollback id stable: %v %+v", err, again)
388			}
389		})
390	
391		t.Run("rollback succeeded", func(t *testing.T) {
392			s, spec := buildRollingBase(t, false)
393			finishRollbackSuccess(t, s, spec, 2)
394			dir := closeStore(t, s)
395			s2, err := Open(dir)
396			if err != nil {
397				t.Fatalf("reopen: %v", err)
398			}
399			defer s2.Close()
400			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
401			if d.Status != DeviceRollbackSucceeded || d.RollbackTarget != "v1" ||
402				!d.RollbackResult || !d.RollbackSuccess ||
403				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
404				t.Fatalf("rollback success restored: %+v", d)
405			}
406			if sh, _ := s2.Get("d1"); sh.Version != "v1" {
407				t.Fatalf("shadow version restored: %s", sh.Version)
408			}
409		})
410	
411		t.Run("rollback failed", func(t *testing.T) {
412			s, spec := buildRollingBase(t, false)
413			finishRollbackFailure(t, s, spec)
414			dir := closeStore(t, s)
415			s2, err := Open(dir)
416			if err != nil {
417				t.Fatalf("reopen: %v", err)
418			}
419			defer s2.Close()
420			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
421			if d.Status != DeviceRollbackFailed || d.RollbackReason != "rb boom" ||
422				!d.RollbackAt.Equal(upBase.Add(9*time.Minute)) ||
423				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
424				t.Fatalf("rollback failure restored: %+v", d)
425			}
426		})
427	
428		t.Run("awaiting rollback timeout", func(t *testing.T) {
429			s := setupUpgrade(t, "d1")
430			spec := rbSpec()
431			createCampaign(t, s, spec)
432			bringOnline(t, s, "d1")
433			awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
434			if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
435				t.Fatal(err)
436			}
437			dir := closeStore(t, s)
438			s2, err := Open(dir)
439			if err != nil {
440				t.Fatalf("reopen: %v", err)
441			}
442			defer s2.Close()
443			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
444			// 等待回滚超时：可以没有回滚领取和结果，但安装失败原因/时间保留。
445			if d.Status != DeviceRollbackTimeout || d.RollbackResult ||
446				d.RollbackID == "" || d.RollbackTarget != "v1" ||
447				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
448				t.Fatalf("awaiting-timeout restored: %+v", d)
449			}
450		})
451	
452		t.Run("rolling back timeout", func(t *testing.T) {
453			s, spec := buildRollingBase(t, false)
454			timeoutRollingBase(t, s, spec)
455			dir := closeStore(t, s)
456			s2, err := Open(dir)
457			if err != nil {
458				t.Fatalf("reopen: %v", err)
459			}
460			defer s2.Close()
461			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
462			// 正在回滚超时：已领取回滚但可以没有回滚结果，安装失败仍保留。
463			if d.Status != DeviceRollbackTimeout || d.RollbackResult ||
464				d.RollbackTarget != "v1" ||
465				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
466				t.Fatalf("rolling-timeout restored: %+v", d)
467			}
468		})
469	}
470	
471	// TestRestoreLaterPlainReportKeepsInstallFailure 保护：安装失败被接受之后的
472	// 普通上报即使改变当前版本，也不否定此前已接受的安装失败；携带这种后续上报
473	// 的回滚记录重开仍合法，回滚待办仍指向锁定目标。
474	func TestRestoreLaterPlainReportKeepsInstallFailure(t *testing.T) {
475		s, spec := buildRollingBase(t, true)
476		if sh, _ := s.Get("d1"); sh.Version != "v9" {
477			t.Fatalf("precondition shadow: %+v", sh)
478		}
479		dir := closeStore(t, s)
480		s2, err := Open(dir)
481		if err != nil {
482			t.Fatalf("reopen with later plain report: %v", err)
483		}
484		defer s2.Close()
485		d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
486		if d.Status != DeviceRollingBack || d.RollbackTarget != "v1" ||
487			d.InstallFailReason != "install broken" {
488			t.Fatalf("rollback with later report restored: %+v", d)
489		}
490		w, _ := s2.GetDeviceWork("d1")
491		if w.Pending == nil || w.Pending.Kind != StageRollback ||
492			w.Pending.TargetVersion != "v1" || w.Version != "v9" {
493			t.Fatalf("todo target stays locked while shadow moved: %+v", w)
494		}
495	}
