298				t.Fatalf("rollback pending work lost: %+v want %+v", w, wantWork)
299			}
300		})
301	
302		// 回滚各终态（成功/失败/超时）都是 failed 结束活动的合法组合，
303		// 未开启回滚的旧活动按原有终态判断同样正常打开。
304		t.Run("terminal rollback campaigns reopen failed", func(t *testing.T) {
305			// 回滚成功
306			s, dir, spec, rb := setupInstallFailure(t, true)
307			if _, err := s.Claim(spec.ID, "d1", upBase.Add(4*time.Minute)); err != nil {
308				t.Fatal(err)
309			}
310			if err := s.SubmitResult(OperationResult{
311				CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
312				At: upBase.Add(5 * time.Minute), Success: true,
313				Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
314			}); err != nil {
315				t.Fatal(err)
316			}
317			s.Close()
318			s2, err := Open(dir)
319			if err != nil {
320				t.Fatalf("rollback-succeeded campaign must reopen failed: %v", err)
321			}
322			cv := mustGetCampaign(s2, spec.ID)
323			if !cv.Ended || cv.Status != CampaignFailed {
324				t.Fatalf("rollback success must end campaign failed: %+v", cv)
325			}
326			s2.Close()
327		})
