1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"testing"
7		"time"
8	)
9	
10	// 操作标识消歧与兼容的回归测试：活动或设备标识含冒号时，
11	// 不同（活动, 设备, 阶段）组合必须拿到互不相同的操作标识。
12	
13	// TestOperationIDDistinguishesColonAmbiguousCampaigns 复现串用场景：
14	// 活动 a:b 中设备 c 与活动 a 中设备 b:c 的同一阶段，旧方案会拼出相同标识。
15	// 两个活动与两台设备都是合法且互不相同的记录，必须各自领取和完成自己的操作。
16	func TestOperationIDDistinguishesColonAmbiguousCampaigns(t *testing.T) {
17		s := setupUpgrade(t, "c", "b:c")
18		specAB := upSpec()
19		specAB.ID = "a:b"
20		specAB.Devices = []string{"c"}
21		specAB.BatchSize = 1
22		createCampaign(t, s, specAB)
23		specA := upSpec()
24		specA.ID = "a"
25		specA.Devices = []string{"b:c"}
26		specA.BatchSize = 1
27		createCampaign(t, s, specA)
28		bringOnline(t, s, "c")
29		bringOnline(t, s, "b:c")
30	
31		at := upBase.Add(time.Minute)
32		opC, err := s.Claim("a:b", "c", at)
33		if err != nil || opC == nil {
34			t.Fatalf("claim a:b/c: %v %+v", err, opC)
35		}
36		opB, err := s.Claim("a", "b:c", at)
37		if err != nil || opB == nil {
38			t.Fatalf("claim a/b:c: %v %+v", err, opB)
39		}
40		if opC.ID == opB.ID {
41			t.Fatalf("ambiguous operation id shared by both campaigns: %q", opC.ID)
42		}
43		// 标识必须明确归属各自的活动、设备与阶段。
44		if !validV2OpID(opC.ID, "a:b", "c", StageDownload) {
45			t.Fatalf("a:b/c download id does not identify its operation: %q", opC.ID)
46		}
47		if !validV2OpID(opB.ID, "a", "b:c", StageDownload) {
48			t.Fatalf("a/b:c download id does not identify its operation: %q", opB.ID)
49		}
50		// 查询设备待办返回的标识与领取的一致，可直接用于提交。
51		if w, err := s.GetDeviceWork("c"); err != nil || w.Pending == nil ||
52			w.Pending.ID != opC.ID || w.CampaignID != "a:b" {
53			t.Fatalf("device work for c: %v %+v", err, w)
54		}
55		if w, err := s.GetDeviceWork("b:c"); err != nil || w.Pending == nil ||
56			w.Pending.ID != opB.ID || w.CampaignID != "a" {
57			t.Fatalf("device work for b:c: %v %+v", err, w)
58		}
59	
60		// 把 a:b/c 的标识用于 a/b:c 的提交：必须拒绝且不改任何状态。
61		submitAt := upBase.Add(2 * time.Minute)
62		err = s.SubmitResult(OperationResult{
63			CampaignID: "a", DeviceID: "b:c", OperationID: opC.ID,
64			At: submitAt, Success: true,
65		})
66		if !errors.Is(err, ErrOperationNotFound) {
67			t.Fatalf("foreign op id must be rejected: %v", err)
68		}
69		// 反向同样拒绝。
70		err = s.SubmitResult(OperationResult{
71			CampaignID: "a:b", DeviceID: "c", OperationID: opB.ID,
72			At: submitAt, Success: true,
73		})
74		if !errors.Is(err, ErrOperationNotFound) {
75			t.Fatalf("foreign op id must be rejected (reverse): %v", err)
76		}
77		// 两边活动进度、结果历史与设备影子都未被改变。
78		for id, dev := range map[string]string{"a:b": "c", "a": "b:c"} {
79			v := mustGetCampaign(s, id)
80			if len(v.Results) != 0 {
81				t.Fatalf("campaign %s history changed by foreign submit: %+v", id, v.Results)
82			}
83			if d := findDevice(v, dev); d.Status != DeviceDownloading {
84				t.Fatalf("campaign %s device %s state changed: %+v", id, dev, d)
85			}
86			sh, err := s.Get(dev)
87			if err != nil || sh.Version != "v1" {
88				t.Fatalf("device %s shadow changed: %v %+v", dev, err, sh)
89			}
90		}
91	
92		// 正确归属的操作继续按原有规则接受：各自完成下载。
93		if err := s.SubmitResult(OperationResult{
94			CampaignID: "a:b", DeviceID: "c", OperationID: opC.ID,
95			At: submitAt, Success: true,
96		}); err != nil {
